const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

function countingLedger() {
  const ledger = new Ledger();
  ledger.applyCalls = 0;
  const apply = ledger.apply.bind(ledger);
  ledger.apply = async (...args) => { ledger.applyCalls++; return apply(...args); };
  return ledger;
}

async function main() {
  // Transient ack after debit: retried with the same receipt, one debit.
  {
    const ledger = countingLedger(); const acks = []; let fail = 2;
    const service = new PaymentService(ledger, { acknowledge: async r => { acks.push(r); if (fail-- > 0) throw new Transient('t'); } });
    const receipt = await service.pay('shop', 'sale', 500);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks.length, 3);
    for (const r of acks) assert.equal(r, receipt);
  }
  // Exhausted retries rethrow the final Transient; attempts total tries.
  {
    const ledger = countingLedger(); let calls = 0; const last = new Transient('final');
    const service = new PaymentService(ledger, { acknowledge: async () => { calls++; throw calls === 2 ? last : new Transient('x'); } });
    await assert.rejects(service.pay('shop', 'exh', 5, 2), e => e === last);
    assert.equal(calls, 2); assert.equal(ledger.entries.length, 1);
  }
  // attempts=1 means a single try.
  {
    const ledger = new Ledger(); let calls = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { calls++; throw new Transient('t'); } });
    await assert.rejects(service.pay('shop', 'one', 5, 1), Transient);
    assert.equal(calls, 1);
  }
  // Non-Transient errors are not retried.
  {
    const ledger = new Ledger(); let calls = 0; const boom = new Error('boom');
    const service = new PaymentService(ledger, { acknowledge: async () => { calls++; throw boom; } });
    await assert.rejects(service.pay('shop', 'boom', 5), e => e === boom);
    assert.equal(calls, 1); assert.equal(ledger.entries.length, 1);
  }
  // Key conflict: different amount under same tenant/key, no second debit, not retried.
  {
    const ledger = countingLedger(); const service = new PaymentService(ledger, { acknowledge: async () => {} });
    await service.pay('shop', 'k', 100);
    await assert.rejects(service.pay('shop', 'k', 200), { message: 'key conflict' });
    assert.equal(ledger.entries.length, 1); assert.equal(ledger.applyCalls, 2);
  }
  // Scope: same key in another tenant is a separate debit.
  {
    const ledger = new Ledger(); const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const a = await service.pay('a', 'k', 100); const b = await service.pay('b', 'k', 200);
    assert.notEqual(a.id, b.id); assert.equal(ledger.entries.length, 2);
  }
  // Concurrent equal calls: one debit, all get the original receipt.
  {
    const ledger = new Ledger(); const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const rs = await Promise.all([1, 2, 3, 4, 5].map(() => service.pay('shop', 'par', 42)));
    assert.equal(ledger.entries.length, 1);
    for (const r of rs) assert.deepEqual(r, { id: 1, tenant: 'shop', key: 'par', cents: 42 });
  }
  // Concurrent conflicting calls: exactly one debit, the other gets key conflict.
  {
    const ledger = new Ledger(); const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const out = await Promise.allSettled([service.pay('shop', 'race', 1), service.pay('shop', 'race', 2)]);
    assert.equal(out.filter(o => o.status === 'fulfilled').length, 1);
    const rej = out.find(o => o.status === 'rejected');
    assert.equal(rej.reason.message, 'key conflict');
    assert.equal(ledger.entries.length, 1);
  }
  // Invalid input: throws before touching ledger or transport.
  {
    const bad = [
      ['', 'k', 1], ['t', '', 1], [undefined, 'k', 1], [null, 'k', 1], [5, 'k', 1], ['t', 7, 1],
      ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', '5'], ['t', 'k', NaN], ['t', 'k', Infinity],
    ];
    for (const [t, k, c] of bad) {
      const ledger = countingLedger(); let acks = 0;
      const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
      await assert.rejects(service.pay(t, k, c), { message: 'invalid payment' });
      assert.equal(ledger.applyCalls, 0); assert.equal(acks, 0);
    }
    for (const a of [0, 6, -1, 1.5, '3', NaN]) {
      const ledger = countingLedger(); let acks = 0;
      const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
      await assert.rejects(service.pay('t', 'k', 1, a), { message: 'invalid payment' });
      assert.equal(ledger.applyCalls, 0); assert.equal(acks, 0);
    }
  }
  // Boundary: attempts 5 is allowed.
  {
    const ledger = new Ledger(); let calls = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { if (++calls < 5) throw new Transient('t'); } });
    await service.pay('shop', 'five', 1, 5); assert.equal(calls, 5);
  }
}
module.exports = main();

